def threeSum(nums):
    nums = sorted(nums); res = []
    for i in range(len(nums) - 2):
        if i and nums[i] == nums[i-1]: continue
        l, h = i + 1, len(nums) - 1
        while l < h:
            s = nums[i] + nums[l] + nums[h]
            if s < 0: l += 1
            elif s > 0: h -= 1
            else:
                res.append([nums[i], nums[l], nums[h]]); l += 1
                while l < h and nums[l] == nums[l-1]: l += 1
    return res
